from collections import deque
test = [[5,5,5,5,5,5,8]+[5]*19 for _ in range(22)]
for r in range(15,19):
    test[r][3:10] = [8]*7
test[16][10:26] = [8]*16
H,W = len(test), len(test[0])
bg = 5
reach = [[False]*W for _ in range(H)]
q = deque()
for r in range(H):
    for c in (0,W-1):
        if test[r][c]==bg: reach[r][c]=True; q.append((r,c))
for c in range(W):
    for r in (0,H-1):
        if test[r][c]==bg: reach[r][c]=True; q.append((r,c))
while q:
    r,c = q.popleft()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc = r+dr,c+dc
        if 0<=nr<H and 0<=nc<W and test[nr][nc]==bg and not reach[nr][nc]:
            reach[nr][nc]=True; q.append((nr,nc))
out = [[4 if test[r][c]==bg and not reach[r][c] else test[r][c] for c in range(W)] for r in range(H)]
for row in out: print(row)
